{
  "code": "import pytest
import impl


def test_usd_simple():
    """Simple USD formatting with 2 decimals."""
    exponents = {"USD": 2}
    assert impl.format_amount("10.50", "USD", exponents) == "10.50"


def test_rounding_half_even_up():
    """ROUND_HALF_EVEN: 2.675 rounds up to 2.68 (to even)."""
    exponents = {"USD": 2}
    assert impl.format_amount("2.675", "USD", exponents) == "2.68"


def test_rounding_half_even_down():
    """ROUND_HALF_EVEN: 2.665 rounds down to 2.66 (to even)."""
    exponents = {"USD": 2}
    assert impl.format_amount("2.665", "USD", exponents) == "2.66"


def test_negative_amount():
    """Negative amounts preserve their sign."""
    exponents = {"USD": 2}
    assert impl.format_amount("-5.50", "USD", exponents) == "-5.50"


def test_jpy_zero_decimals():
    """JPY with 0 decimals produces no decimal point."""
    exponents = {"JPY": 0}
    result = impl.format_amount("1234.5", "JPY", exponents)
    assert result == "1234"
    assert "." not in result


def test_multiple_decimal_places():
    """Test currencies with 3 and 4 decimal places."""
    exponents = {"KWD": 3, "CLF": 4}
    assert impl.format_amount("1.2345", "KWD", exponents) == "1.235"
    assert impl.format_amount("1.23456", "CLF", exponents) == "1.2346"


def test_zero_padding():
    """Output is zero-padded to the correct number of decimals."""
    exponents = {"USD": 2}
    assert impl.format_amount("10", "USD", exponents) == "10.00"
    exponents = {"KWD": 3}
    assert impl.format_amount("10", "KWD", exponents) == "10.000"


def test_negative_zero():
    """Negative zero is rendered as unsigned zero."""
    exponents = {"USD": 2}
    assert impl.format_amount("-0.004", "USD", exponents) == "0.00"
    exponents = {"JPY": 0}
    assert impl.format_amount("-0.4", "JPY", exponents) == "0"


def test_scientific_notation():
    """Scientific notation in input is parsed correctly."""
    exponents = {"USD": 2}
    assert impl.format_amount("1E+2", "USD", exponents) == "100.00"
    assert impl.format_amount("1.5e-3", "USD", exponents) == "0.00"


def test_whitespace():
    """Leading and trailing whitespace in amount is accepted."""
    exponents = {"USD": 2}
    assert impl.format_amount("  10.50  ", "USD", exponents) == "10.50"


def test_explicit_positive_sign():
    """Explicit positive sign in input is handled (no + in output)."""
    exponents = {"USD": 2}
    assert impl.format_amount("+10.50", "USD", exponents) == "10.50"


def test_no_exponent_in_output():
    """Large numbers have no exponent notation in output."""
    exponents = {"USD": 2}
    result = impl.format_amount("123456789012345.50", "USD", exponents)
    assert result == "123456789012345.50"
    assert "e" not in result.lower()


def test_unknown_currency_raised_first():
    """KeyError is raised for unknown currency before parsing amount."""
    exponents = {"USD": 2}
    with pytest.raises(KeyError):
        impl.format_amount("invalid_amount", "XXX", exponents)


def test_invalid_empty_string():
    """ValueError raised for empty amount string."""
    exponents = {"USD": 2}
    with pytest.raises(ValueError):
        impl.format_amount("", "USD", exponents)


def test_invalid_non_numeric():
    """ValueError raised for non-numeric strings."""
    exponents = {"USD": 2}
    with pytest.raises(ValueError):
        impl.format_amount("abc", "USD", exponents)


def test_invalid_malformed_decimal():
    """ValueError raised for malformed decimals."""
    exponents = {"USD": 2}
    with pytest.raises(ValueError):
        impl.format_amount("1.2.3", "USD", exponents)


def test_invalid_special_formats():
    """ValueError raised for amounts with special formats."""
    exponents = {"USD": 2}
    with pytest.raises(ValueError):
        impl.format_amount("12,34", "USD", exponents)  # comma decimal
    with pytest.raises(ValueError):
        impl.format_amount("$1.00", "USD", exponents)  # currency symbol
    with pytest.raises(ValueError):
        impl.format_amount("1 000.00", "USD", exponents)  # space separator


def test_non_finite_values():
    """ValueError raised for NaN and Infinity values."""
    exponents = {"USD": 2}
    with pytest.raises(ValueError):
        impl.format_amount("NaN", "USD", exponents)
    with pytest.raises(ValueError):
        impl.format_amount("Infinity", "USD", exponents)
    with pytest.raises(ValueError):
        impl.format_amount("-Infinity", "USD", exponents)


def test_edge_cases():
    """Test various edge cases."""
    exponents = {"USD": 2}
    # More decimals than target
    assert impl.format_amount("10.12345", "USD", exponents) == "10.12"
    # Fewer decimals than target
    assert impl.format_amount("10.1", "USD", exponents) == "10.10"
    # No decimals in input
    assert impl.format_amount("100", "USD", exponents) == "100.00"
